package com.flippingfriend.companion;
import com.flippingfriend.model.TaxCalculator; import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementUnwindLossEvaluatorTest {
 @Test public void appliesProductionUnwindArithmeticInOrder(){BuyReplacementUnwindLossInputContext s=source();BuyReplacementUnwindLossEvaluationSet r=evaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getEvaluations().size(),r.getEvaluations().size());double buckets=Math.max(1.0,s.getEffectiveHorizonHours()*(3600.0/s.getBucketSeconds()));double drift=Math.max(0.002,0.25*Math.min(0.2,s.getVolatility())*Math.sqrt(buckets));TaxCalculator tax=new TaxCalculator();for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementExpectedSlotOccupancyEvaluation a=s.getEvaluations().get(i);BuyReplacementUnwindLossEvaluation e=r.getEvaluations().get(i);int exit=Math.max(1,(int)Math.round(Math.min(a.getBuyPrice(),s.getCurrentLowPrice())*(1-drift)));int exitTax=tax.taxPerItem(s.getItemId(),exit);long loss=Math.max(0,(long)a.getBuyPrice()-((long)exit-exitTax));assertEquals(drift,e.getDriftFraction(),0.0);assertEquals(exit,e.getExitPrice());assertEquals(exitTax,e.getExitTaxPerItem());assertEquals(loss,e.getLossPerItem());assertEquals(loss*a.getExactRemainderQuantity(),e.getTotalUnwindLoss());assertEquals(a.getSellOffsetIndex(),e.getSellOffsetIndex());}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){assertNull(evaluator().evaluate(null,1100));assertNull(new BuyReplacementUnwindLossEvaluator(null).evaluate(source(),1100));assertNull(evaluator().evaluate(source(),1221));}
 @Test public void contractsCarryNoProfitRiskRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementUnwindLossEvaluation.java","BuyReplacementUnwindLossEvaluationSet.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"expectedProfit","worstLoss","kelly","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementUnwindLossEvaluationSet evaluationSetForCompanionTests(){return evaluator().evaluate(source(),1100);} private static BuyReplacementUnwindLossEvaluator evaluator(){return new BuyReplacementUnwindLossEvaluator(new TaxCalculator());} private static BuyReplacementUnwindLossInputContext source(){return BuyReplacementUnwindLossInputContextComposerTest.evaluationContextForCompanionTests();}
}
